SELECT "IdUsuario","Clave","FechaVigencia","IdEstado","IntentosConexion","FechaBloqueoTemporal","EsAutorizado", "TipoEntidad", "IdEntidad","UsuarioClientes", "UsuarioNegocios", "UsuarioServicios", "UsuarioCorredores",c1."Valor" as "Param_FechaSistema",c2."Valor" as "Param_IntentosMaximo",CURRENT_UTCTIMESTAMP as "CurrentTimestamp",c3."Valor" AS "Param_ClaveUsuarioTiempoBloqueo" FROM "BSCL.Plataforma.BD::ACC.Usuario" u LEFT JOIN "BSCL.Plataforma.BD::PLA.Configuracion" c1 ON u."IdEmpresa" = c1."IdEmpresa" AND c1."CodigoParametro" = 'PLA.FechaSistema' LEFT JOIN "BSCL.Plataforma.BD::PLA.Configuracion" c2 ON u."IdEmpresa" = c2."IdEmpresa" AND c2."CodigoParametro" = 'PLA.ClaveUsuarioIntentos' LEFT JOIN "BSCL.Plataforma.BD::PLA.Configuracion" c3 ON u."IdEmpresa" = c3."IdEmpresa" AND c3."CodigoParametro" = 'PLA.ClaveUsuarioTiempoBloqueo' WHERE u."IdEmpresa" = :p_IdEmpresa AND "CodigoUsuario" = :p_NombreUsuario